@layer el-themes {
[data-theme="mono-console"] {
  --el-bg:           #0a0a0a;
  --el-panel:        #101010;
  --el-panel-2:      #141414;
  --el-panel-3:      #1b1b1b;

  --el-line:         #262626;
  --el-line-2:       #1a1a1a;
  --el-line-strong:  #343434;

  --el-ink:          #e8e8e8;
  --el-ink-soft:     #9c9c9c;
  
  --el-mute:         #8a8a8a;
  --el-on-accent:    #04150b;

  --el-accent:        #3ddc84;
  --el-accent-hover:  #66ef9f;
  --el-accent-soft:   color-mix(in oklab, var(--el-accent) 12%, transparent);

  --el-ok:    #56d364;
  --el-warn:  #e3b341;
  --el-fail:  #f85149;
  --el-info:  #5cc8ff;
  --el-live:  #2ee6a6;
  --el-teal:  #35c0ae;

  --el-focus-ring: color-mix(in oklab, var(--el-accent) 55%, transparent);

  --el-font-display:  'Geist', 'Inter Tight', system-ui, sans-serif;
  --el-font-body:     'Inter Tight', system-ui, sans-serif;
  --el-font-mono:     'JetBrains Mono', 'SF Mono', Menlo, Consolas, monospace;

  
  --el-r-sm:  2px;
  --el-r-md:  3px;
  --el-r-lg:  4px;
  --el-r-xl:  6px;
  --el-r-pill: 2px;

  --el-raise-1: 0 1px 0 rgba(0, 0, 0, 0.55);
  --el-raise-2: 0 0 0 1px color-mix(in oklab, var(--el-line-strong) 82%, var(--el-bg)), 0 10px 30px -14px rgba(0, 0, 0, 0.75);
  --el-raise-3: 0 0 0 1px color-mix(in oklab, var(--el-line-strong) 88%, var(--el-bg)), 0 24px 64px -20px rgba(0, 0, 0, 0.85);

  --el-bar-h: 2px;
  --el-ctl-pad-y: 6px;
  --el-ctl-pad-x: 12px;
  --el-ctl-min-h: 34px;
  --el-card-pad: 16px;

  --el-head-weight: 700;
  --el-head-tracking: -0.02em;
  --el-head-case: uppercase;

  --el-label-weight: 600;
  --el-label-tracking: 0.16em;
  --el-label-case: uppercase;

  --el-body-weight: 500;

  --el-dur-fast: 120ms;
  --el-dur-base: 180ms;
  --el-ease: cubic-bezier(.2, 0, .2, 1);

  --el-ornament: repeating-linear-gradient(180deg, color-mix(in oklab, var(--el-accent) 3%, transparent) 0 1px, transparent 1px 4px);
  --el-rule-style: solid;

  --el-hero-pad: 48px;
  --el-hero-min: 340px;

  --el-stage-active:  var(--el-accent);
  --el-stage-done:    var(--el-ok);
  --el-stage-running: var(--el-accent);
  --el-stage-stale:   var(--el-fail);

  
  --el-hairline:     inset 0 1px 0 color-mix(in oklab, var(--el-ink) 5%, transparent);
  --el-edge:         var(--el-line);
  --el-ring:         0 0 0 3px color-mix(in oklab, var(--el-accent) 18%, transparent);
  --el-ring-strong:  0 0 0 3px color-mix(in oklab, var(--el-accent) 28%, transparent);
  --el-inset-field:  inset 0 1px 2px rgba(0, 0, 0, 0.5);
  --el-lift:         translateY(-1px);
  --el-press:        scale(0.99);
  --el-ease-out:     cubic-bezier(.22, 1, .36, 1);
  --el-ease-quiet:   cubic-bezier(.32, .72, .36, 1);
  --el-measure:      68ch;
  --el-dur-surface:  240ms;
  --el-dur-flow:     320ms;
  --el-dur-progress: 480ms;

  
  --el-row-h: 34px;

  color-scheme: dark;
  accent-color: var(--el-accent);
  scrollbar-color: var(--el-line-strong) transparent;
}

[data-theme="mono-console"] body {
  margin: 0;
  background-color: var(--el-bg);
  background-image:
    radial-gradient(1200px 620px at 4% -6%,
      color-mix(in oklab, var(--el-accent) 10%, transparent) 0%,
      color-mix(in oklab, var(--el-accent) 6%, transparent) 26%,
      color-mix(in oklab, var(--el-accent) 2.5%, transparent) 48%,
      transparent 68%),
    repeating-linear-gradient(180deg,
      color-mix(in oklab, var(--el-accent) 2.4%, transparent) 0 1px,
      transparent 1px 4px);
  background-repeat: no-repeat, repeat;
  background-size: 1200px 620px, auto;
  color: var(--el-ink);
  font-family: var(--el-font-body);
  font-size: var(--el-fs-md);
  font-weight: var(--el-body-weight);
  line-height: 1.6;
  font-optical-sizing: auto;
  -webkit-font-smoothing: antialiased;
}
[data-theme="mono-console"] ::selection { background: var(--el-accent); color: var(--el-on-accent); }

[data-theme="mono-console"] h1,
[data-theme="mono-console"] h2,
[data-theme="mono-console"] h3,
[data-theme="mono-console"] h4 {
  font-family: var(--el-font-display);
  font-weight: var(--el-head-weight);
  letter-spacing: var(--el-head-tracking);
  text-transform: var(--el-head-case);
  line-height: 1.16;
  text-wrap: balance;
  color: var(--el-ink);
  margin: 0.35em 0;
}

[data-theme="mono-console"] .el-label,
[data-theme="mono-console"] .el-eyebrow {
  font-family: var(--el-font-mono);
  font-size: var(--el-fs-xs);
  font-weight: var(--el-label-weight);
  letter-spacing: var(--el-label-tracking);
  text-transform: var(--el-label-case);
  color: var(--el-ink-soft);
  text-shadow: 0 1px 0 rgba(0, 0, 0, 0.9);
}
[data-theme="mono-console"] .el-eyebrow { color: var(--el-accent); }
[data-theme="mono-console"] .el-eyebrow::before { content: "> "; }

[data-theme="mono-console"] .el-body {
  font-size: var(--el-fs-md);
  font-weight: var(--el-body-weight);
  color: var(--el-ink-soft);
  line-height: 1.6;
}
[data-theme="mono-console"] .el-mute-body {
  font-family: var(--el-font-mono);
  font-size: var(--el-fs-sm);
  color: var(--el-mute);
}
[data-theme="mono-console"] .el-mono {
  font-family: var(--el-font-mono);
  font-size: var(--el-fs-sm);
  color: var(--el-ink-soft);
  font-feature-settings: "tnum" 1;
}
[data-theme="mono-console"] .el-ink-ok    { font-family: var(--el-font-mono); color: var(--el-ok); }
[data-theme="mono-console"] .el-ink-fail  { font-family: var(--el-font-mono); color: var(--el-fail); }

[data-theme="mono-console"] .el-title-xl,
[data-theme="mono-console"] .el-display-specimen {
  font-family: var(--el-font-display);
  font-weight: var(--el-head-weight);
  letter-spacing: var(--el-head-tracking);
  text-transform: var(--el-head-case);
  text-wrap: balance;
  color: var(--el-ink);
}
[data-theme="mono-console"] .el-title-xl {
  line-height: 1.04;
  animation: el-mono-type 520ms steps(20, end) 80ms both;
}

[data-theme="mono-console"] .el-field { display: block; margin-bottom: var(--el-space-3); }
[data-theme="mono-console"] .el-field .el-label { display: block; margin-bottom: 6px; }

[data-theme="mono-console"] .el-hero {
  position: relative;
  box-sizing: border-box;
  border: 1px solid var(--el-line);
  border-left: 2px solid var(--el-accent);
  border-radius: var(--el-r-lg);
  background-color: color-mix(in oklab, var(--el-panel) 72%, var(--el-bg));
  background-image: var(--el-ornament);
  box-shadow: var(--el-raise-1), var(--el-hairline);
}
[data-theme="mono-console"] .el-hero .el-body { max-width: 560px; }

[data-theme="mono-console"] .el-title-xl::after {
  content: "";
  display: inline-block;
  width: 0.46em;
  height: 0.82em;
  margin-left: 0.16em;
  transform: translateY(0.1em);
  background: var(--el-accent);
  opacity: var(--el-caret-blink);
  animation: el-mono-caret 1.08s linear infinite;
}

[data-theme="mono-console"] .el-btn {
  font-family: var(--el-font-mono);
  font-size: var(--el-fs-sm);
  font-weight: 600;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--el-ink);
  background: var(--el-panel-3);
  background-image: none;
  border: 1px solid var(--el-line-strong);
  border-radius: var(--el-r-sm);
  box-shadow: none;
  transition: color var(--el-dur-fast) var(--el-ease),
              border-color var(--el-dur-fast) var(--el-ease),
              background var(--el-dur-fast) var(--el-ease),
              transform var(--el-dur-fast) var(--el-ease);
}
[data-theme="mono-console"] .el-btn:hover {
  filter: none;
  transform: none;
  box-shadow: none;
  color: var(--el-accent);
  background: color-mix(in oklab, var(--el-accent) 10%, var(--el-panel-3));
  border-color: color-mix(in oklab, var(--el-accent) 55%, var(--el-line-strong));
}
[data-theme="mono-console"] .el-btn:focus-visible {
  outline: 2px solid var(--el-focus-ring);
  outline-offset: 2px;
}
[data-theme="mono-console"] .el-btn:active {
  transform: translateY(1px);
  background: color-mix(in oklab, var(--el-accent) 14%, var(--el-panel-3));
  box-shadow: none;
  outline: none;
}
[data-theme="mono-console"] .el-btn:disabled,
[data-theme="mono-console"] .el-btn[aria-disabled="true"] {
  opacity: 0.45;
  cursor: not-allowed;
  color: var(--el-ink-soft);
  background: var(--el-panel-2);
  border-color: var(--el-line);
  box-shadow: none;
  transform: none;
}
[data-theme="mono-console"] .el-btn.ghost,
[data-theme="mono-console"] .el-btn--ghost,
[data-theme="mono-console"] .el-btn--outline {
  background: transparent;
  border-color: transparent;
  color: var(--el-ink-soft);
}
[data-theme="mono-console"] .el-btn.ghost:hover,
[data-theme="mono-console"] .el-btn--ghost:hover,
[data-theme="mono-console"] .el-btn--outline:hover {
  color: var(--el-accent);
  border-color: var(--el-line-strong);
  background: color-mix(in oklab, var(--el-accent) 6%, transparent);
}
[data-theme="mono-console"] .el-btn.ghost:active,
[data-theme="mono-console"] .el-btn--ghost:active,
[data-theme="mono-console"] .el-btn--outline:active {
  transform: translateY(1px);
  background: color-mix(in oklab, var(--el-accent) 12%, transparent);
}
[data-theme="mono-console"] .el-btn.ghost:disabled,
[data-theme="mono-console"] .el-btn--ghost:disabled,
[data-theme="mono-console"] .el-btn--outline:disabled {
  background: transparent;
  border-color: transparent;
  color: var(--el-mute);
}

[data-theme="mono-console"] .el-card {
  background: var(--el-panel);
  background-image: var(--el-ornament);
  border: 1px solid var(--el-line);
  border-radius: var(--el-r-lg);
  box-shadow: var(--el-raise-1), var(--el-hairline);
}
[data-theme="mono-console"] .el-card::before {
  height: var(--el-bar-h);
  background: linear-gradient(90deg, var(--el-accent) 0 22px, var(--el-line) 22px);
  opacity: 1;
}
[data-theme="mono-console"] .el-card:hover {
  transform: none;
  border-color: color-mix(in oklab, var(--el-accent) 38%, var(--el-line));
  box-shadow: var(--el-raise-2), var(--el-hairline);
}
[data-theme="mono-console"] .el-card:focus-within { border-color: var(--el-accent); }

[data-theme="mono-console"] .el-stage-rail {
  background: color-mix(in oklab, var(--el-panel) 55%, var(--el-bg));
  border-radius: var(--el-r-sm);
}
[data-theme="mono-console"] .el-source-card {
  font-family: var(--el-font-mono);
  background: var(--el-panel);
  background-image: var(--el-ornament);
  border-radius: var(--el-r-sm);
}
[data-theme="mono-console"] .el-publisher {
  font-family: var(--el-font-mono);
  font-size: var(--el-fs-xs);
  font-weight: var(--el-label-weight);
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--el-accent);
}

[data-theme="mono-console"] .el-big-num {
  font-family: var(--el-font-mono);
  font-weight: 600;
  font-variant-numeric: tabular-nums;
  letter-spacing: -0.01em;
  color: var(--el-accent);
  background-image: none;
  -webkit-text-fill-color: currentColor;
}
[data-theme="mono-console"] .el-big-num .total,
[data-theme="mono-console"] .el-big-num .lbl { -webkit-text-fill-color: var(--el-ink-soft); }

[data-theme="mono-console"] .el-bar {
  position: relative;
  height: 6px;
  margin: var(--el-space-2) 0;
  background: var(--el-panel-3);
  border: 1px solid var(--el-line);
  overflow: hidden;
}
[data-theme="mono-console"] .el-bar i {
  position: absolute;
  inset: 0 auto 0 0;
  display: block;
  height: 100%;
  background-color: var(--el-accent);
  background-image: repeating-linear-gradient(90deg, transparent 0 4px, rgba(10, 10, 10, 0.75) 4px 5px);
}

[data-theme="mono-console"] .el-table {
  font-family: var(--el-font-mono);
  font-size: var(--el-fs-sm);
  background: var(--el-bg);
  border: 1px solid var(--el-line);
  border-radius: var(--el-r-sm);
  box-shadow: none;
}
[data-theme="mono-console"] .el-table thead th {
  background: var(--el-panel-2);
  color: var(--el-mute);
  font-family: var(--el-font-mono);
  font-size: var(--el-fs-xs);
  font-weight: var(--el-label-weight);
  letter-spacing: var(--el-label-tracking);
  text-transform: uppercase;
  border-bottom: 1px solid var(--el-line-strong);
}
[data-theme="mono-console"] .el-table tbody td {
  padding: var(--el-space-2) var(--el-space-3);
  border-bottom: 1px solid var(--el-line-2);
  font-variant-numeric: tabular-nums;
}
[data-theme="mono-console"] .el-table tbody tr:hover {
  background: color-mix(in oklab, var(--el-accent) 16%, var(--el-panel-2));
}
[data-theme="mono-console"] .el-table tbody tr:hover td { color: var(--el-ink); }
[data-theme="mono-console"] .el-table tbody tr:hover td:first-child {
  box-shadow: inset 2px 0 0 var(--el-accent);
}
[data-theme="mono-console"] .el-table tbody tr:active td:first-child {
  box-shadow: inset 2px 0 0 color-mix(in oklab, var(--el-accent) 72%, var(--el-line-strong));
}
[data-theme="mono-console"] .el-table tbody tr:focus-visible {
  outline: 2px solid var(--el-focus-ring);
  outline-offset: -2px;
  background: var(--el-panel-2);
}
[data-theme="mono-console"] .el-table tbody tr[aria-disabled="true"] { opacity: 0.45; }

[data-theme="mono-console"] .el-pill {
  font-family: var(--el-font-mono);
  font-weight: var(--el-label-weight);
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--el-ink-soft);
  border-radius: var(--el-r-sm);
}
[data-theme="mono-console"] .el-pill:hover {
  border-color: color-mix(in oklab, currentColor 48%, transparent);
  background: color-mix(in oklab, currentColor 14%, var(--el-panel));
}
[data-theme="mono-console"] .el-pill:focus-visible {
  outline: 2px solid var(--el-focus-ring);
  outline-offset: 2px;
}
[data-theme="mono-console"] .el-pill:active { transform: translateY(1px); }
[data-theme="mono-console"] .el-pill[aria-disabled="true"] { opacity: 0.45; }

[data-theme="mono-console"] .el-chip {
  font-family: var(--el-font-mono);
  border-radius: var(--el-r-sm);
  letter-spacing: 0.06em;
}
[data-theme="mono-console"] .el-chip.live {
  color: var(--el-accent);
  background: color-mix(in oklab, var(--el-accent) 12%, transparent);
  border-color: color-mix(in oklab, var(--el-accent) 40%, transparent);
}
[data-theme="mono-console"] .el-chip:hover {
  background: color-mix(in oklab, var(--el-accent) 10%, var(--el-panel-2));
  border-color: color-mix(in oklab, var(--el-accent) 46%, var(--el-line));
}
[data-theme="mono-console"] .el-chip:focus-visible {
  outline: 2px solid var(--el-focus-ring);
  outline-offset: 2px;
}
[data-theme="mono-console"] .el-chip:active {
  transform: translateY(1px);
  background: color-mix(in oklab, var(--el-accent) 16%, var(--el-panel-2));
}
[data-theme="mono-console"] .el-chip[aria-disabled="true"] { opacity: 0.45; }

[data-theme="mono-console"] .el-dot { border-radius: 1px; }
[data-theme="mono-console"] .el-dot.ok,
[data-theme="mono-console"] .el-dot.warn,
[data-theme="mono-console"] .el-dot.fail,
[data-theme="mono-console"] .el-dot.live {
  box-shadow: 0 0 0 2px color-mix(in oklab, currentColor 22%, transparent);
}

[data-theme="mono-console"] .el-switch { border-radius: var(--el-r-sm); }
[data-theme="mono-console"] .el-switch::after { border-radius: 1px; }
[data-theme="mono-console"] .el-switch:hover {
  border-color: color-mix(in oklab, var(--el-accent) 45%, var(--el-line-strong));
}
[data-theme="mono-console"] .el-switch:focus-visible {
  outline: 2px solid var(--el-focus-ring);
  outline-offset: 2px;
}
[data-theme="mono-console"] .el-switch:has(> .on),
[data-theme="mono-console"] .el-switch.on {
  background: color-mix(in oklab, var(--el-accent) 26%, var(--el-panel-3));
  border-color: color-mix(in oklab, var(--el-accent) 70%, var(--el-line));
}
[data-theme="mono-console"] .el-switch:has(> .on)::after,
[data-theme="mono-console"] .el-switch.on::after {
  transform: translateX(22px);
  background: var(--el-accent);
  box-shadow: none;
}
[data-theme="mono-console"] .el-switch[aria-disabled="true"] { opacity: 0.45; }

[data-theme="mono-console"] .el-input {
  font-family: var(--el-font-mono);
  font-size: var(--el-fs-sm);
  padding-left: calc(var(--el-ctl-pad-x) + 10px);
  color: var(--el-ink);
  background-color: color-mix(in oklab, var(--el-bg) 55%, var(--el-panel));
  background-image: linear-gradient(var(--el-accent), var(--el-accent));
  background-size: 2px 12px;
  background-position: 9px 50%;
  background-repeat: no-repeat;
  border: 1px solid var(--el-line);
  border-radius: var(--el-r-sm);
  caret-color: var(--el-accent);
  caret-shape: block;
}
[data-theme="mono-console"] .el-input:hover {
  border-color: var(--el-line-strong);
  background-color: color-mix(in oklab, var(--el-bg) 42%, var(--el-panel));
}
[data-theme="mono-console"] .el-input:focus,
[data-theme="mono-console"] .el-input:focus-visible {
  background-color: var(--el-panel-2);
  border-color: var(--el-accent);
  box-shadow: var(--el-ring), inset 0 0 0 1px color-mix(in oklab, var(--el-accent) 45%, transparent);
}
[data-theme="mono-console"] .el-input:active {
  background-color: color-mix(in oklab, var(--el-panel-2) 70%, var(--el-panel-3));
}
[data-theme="mono-console"] .el-input:disabled,
[data-theme="mono-console"] .el-input[aria-disabled="true"] {
  opacity: 0.45;
  cursor: not-allowed;
  background-image: none;
  border-color: var(--el-line);
  box-shadow: none;
}
[data-theme="mono-console"] .el-input::placeholder {
  color: var(--el-mute);
  font-weight: 400;
}

[data-theme="mono-console"] .el-stage {
  font-family: var(--el-font-mono);
  font-size: var(--el-fs-sm);
  letter-spacing: 0.04em;
}
[data-theme="mono-console"] .el-stage:hover {
  background: color-mix(in oklab, var(--el-accent) 10%, transparent);
  color: var(--el-ink);
}
[data-theme="mono-console"] .el-stage:focus-visible {
  outline: 2px solid var(--el-focus-ring);
  outline-offset: 1px;
}
[data-theme="mono-console"] .el-stage:active { transform: translateY(1px); }
[data-theme="mono-console"] .el-stage[aria-disabled="true"] { opacity: 0.45; }
[data-theme="mono-console"] .el-stage-dot { border-radius: 1px; }
[data-theme="mono-console"] .el-stage.done { color: var(--el-ink-soft); }
[data-theme="mono-console"] .el-stage.done .el-stage-dot { background: var(--el-ok); }
[data-theme="mono-console"] .el-stage.run { color: var(--el-accent); }
[data-theme="mono-console"] .el-stage.run .el-stage-dot {
  background: var(--el-accent);
  box-shadow: none;
  animation: el-mono-tick 900ms steps(2, jump-none) infinite;
}

[data-theme="mono-console"] .el-progress-truth {
  font-family: var(--el-font-mono);
  font-size: var(--el-fs-xs);
  border: 1px solid var(--el-line);
  border-radius: var(--el-r-sm);
}
[data-theme="mono-console"] .el-progress-truth .el-pt-chunk {
  border-radius: 1px;
}
[data-theme="mono-console"] .el-progress-truth .el-pt-chunk.on {
  border-color: var(--el-ok);
  color: var(--el-ink);
}
[data-theme="mono-console"] .el-progress-truth .el-pt-label {
  font-family: var(--el-font-mono);
