[data-theme="ghost-terminal"] {
  --el-bg:           #0c0b08;
  --el-panel:        #141108;
  --el-panel-2:      #1a1509;
  --el-panel-3:      #231c0a;

  --el-line:         #3a2e12;
  --el-line-2:       #2a210e;
  --el-line-strong:  #51400f;

  --el-ink:          #ffc233;
  --el-ink-soft:     #d99a2b;
  --el-mute:         #9a7a2c;
  --el-on-accent:    #1a1103;

  --el-accent:        #ffb000;
  --el-accent-hover:  #ffc94d;
  --el-accent-soft:   color-mix(in oklab, var(--el-accent) 12%, transparent);

  --el-ok:    #ffdf8a;
  --el-warn:  #ffb000;
  --el-fail:  #ff5525;
  --el-info:  #ffd894;
  --el-live:  #ff9e1b;
  --el-teal:  #e8a13a;

  --el-focus-ring: color-mix(in oklab, var(--el-accent) 55%, transparent);

  --el-font-display:  'Geist Mono', 'JetBrains Mono', monospace;
  --el-font-body:     'Archivo', system-ui, sans-serif;
  --el-font-mono:     'JetBrains Mono', 'SF Mono', Menlo, Consolas, monospace;

  
  --el-r-sm:  2px;
  --el-r-md:  2px;
  --el-r-lg:  2px;
  --el-r-xl:  2px;
  --el-r-pill: 2px;

  --el-raise-1: 0 0 0 1px color-mix(in oklab, var(--el-accent) 10%, transparent);
  --el-raise-2: 0 0 0 1px color-mix(in oklab, var(--el-accent) 18%, transparent), 0 0 24px color-mix(in oklab, var(--el-accent) 12%, transparent);
  --el-raise-3: 0 0 0 1px color-mix(in oklab, var(--el-accent) 24%, transparent), 0 0 48px color-mix(in oklab, var(--el-accent) 18%, transparent);

  --el-bar-h: 0;
  --el-ctl-pad-y: 7px;
  --el-ctl-pad-x: 13px;
  --el-ctl-min-h: 36px;
  --el-card-pad: 18px;

  --el-head-weight: 700;
  --el-head-tracking: 0.01em;
  --el-head-case: uppercase;

  --el-label-weight: 600;
  --el-label-tracking: 0.2em;
  --el-label-case: uppercase;

  --el-body-weight: 500;

  --el-dur-fast: 120ms;
  --el-dur-base: 180ms;
  --el-ease: cubic-bezier(.3, 0, .2, 1);

  --el-ornament: repeating-linear-gradient(180deg, color-mix(in oklab, var(--el-accent) 5%, transparent) 0 1px, transparent 1px 3px);
  --el-rule-style: dashed;

  --el-hero-pad: 52px;
  --el-hero-min: 360px;

  --el-stage-active:  var(--el-accent);
  --el-stage-done:    var(--el-ok);
  --el-stage-running: var(--el-accent);
  --el-stage-stale:   var(--el-fail);

  
  --el-hairline:     inset 0 1px 0 color-mix(in oklab, var(--el-ink) 6%, transparent);
  --el-edge:         var(--el-line);
  --el-ring:         0 0 0 3px color-mix(in oklab, var(--el-accent) 18%, transparent);
  --el-ring-strong:  0 0 0 3px color-mix(in oklab, var(--el-accent) 28%, transparent);
  --el-inset-field:  inset 0 1px 2px rgba(0, 0, 0, 0.55);
  --el-lift:         translateY(-1px);
  --el-press:        scale(0.99);
  --el-ease-out:     cubic-bezier(.22, 1, .36, 1);
  --el-ease-quiet:   cubic-bezier(.32, .72, .36, 1);
  --el-measure:      68ch;
  --el-dur-surface:  240ms;
  --el-dur-flow:     340ms;
  --el-dur-progress: 500ms;

  
  --el-row-h: 34px;

  color-scheme: dark;
  accent-color: var(--el-accent);
  scrollbar-color: var(--el-line-strong) transparent;
}

[data-theme="ghost-terminal"] body {
  margin: 0;
  background-color: var(--el-bg);
  background-image:
    radial-gradient(1100px 560px at 10% -8%,
      color-mix(in oklab, var(--el-accent) 6.5%, transparent) 0%,
      color-mix(in oklab, var(--el-accent) 4%, transparent) 30%,
      color-mix(in oklab, var(--el-accent) 1.5%, transparent) 54%,
      transparent 72%),
    radial-gradient(920px 540px at 96% 106%,
      color-mix(in oklab, var(--el-teal) 8%, transparent) 0%,
      color-mix(in oklab, var(--el-teal) 4%, transparent) 32%,
      color-mix(in oklab, var(--el-teal) 1.5%, transparent) 52%,
      transparent 70%),
    repeating-linear-gradient(180deg,
      color-mix(in oklab, var(--el-accent) 2.6%, transparent) 0 1px,
      transparent 1px 3px);
  background-repeat: no-repeat, no-repeat, repeat;
  background-size: 1100px 560px, 920px 540px, auto;
  color: var(--el-ink);
  font-family: var(--el-font-body);
  font-size: var(--el-fs-md);
  font-weight: var(--el-body-weight);
  line-height: 1.6;
  font-optical-sizing: auto;
  -webkit-font-smoothing: antialiased;
}
[data-theme="ghost-terminal"] ::selection { background: var(--el-accent); color: var(--el-on-accent); }

[data-theme="ghost-terminal"] h1,
[data-theme="ghost-terminal"] h2,
[data-theme="ghost-terminal"] h3,
[data-theme="ghost-terminal"] h4 {
  font-family: var(--el-font-display);
  font-weight: var(--el-head-weight);
  letter-spacing: var(--el-head-tracking);
  text-transform: var(--el-head-case);
  line-height: 1.2;
  text-wrap: balance;
  color: var(--el-ink);
  margin: 0.45em 0;
}

[data-theme="ghost-terminal"] .el-title-xl,
[data-theme="ghost-terminal"] .el-display-specimen,
[data-theme="ghost-terminal"] h1,
[data-theme="ghost-terminal"] h2,
[data-theme="ghost-terminal"] h3,
[data-theme="ghost-terminal"] h4 {
  text-shadow:
    0 0 20px color-mix(in oklab, var(--el-accent) 28%, transparent),
    0 0 2px color-mix(in oklab, var(--el-accent) 35%, transparent);
}

[data-theme="ghost-terminal"] .el-label,
[data-theme="ghost-terminal"] .el-eyebrow {
  font-family: var(--el-font-mono);
  font-size: var(--el-fs-xs);
  font-weight: var(--el-label-weight);
  letter-spacing: var(--el-label-tracking);
  text-transform: uppercase;
  color: var(--el-mute);
}
[data-theme="ghost-terminal"] .el-eyebrow {
  color: var(--el-accent);
  text-shadow: 0 0 12px color-mix(in oklab, var(--el-accent) 45%, transparent);
}

[data-theme="ghost-terminal"] .el-eyebrow::before {
  content: "";
  display: inline-block;
  width: 8px;
  height: 8px;
  margin-right: 9px;
  background: var(--el-accent);
  box-shadow: 0 0 10px color-mix(in oklab, var(--el-accent) 70%, transparent), 0 0 0 1px color-mix(in oklab, var(--el-accent) 40%, transparent);
  animation: el-ghost-persist 2.8s linear infinite;
}

[data-theme="ghost-terminal"] .el-body {
  font-size: var(--el-fs-md);
  font-weight: var(--el-body-weight);
  color: var(--el-ink-soft);
  line-height: 1.6;
}
[data-theme="ghost-terminal"] .el-mute-body {
