[data-theme="ghost-terminal"] .el-ink-ok    { font-family: var(--el-font-mono); color: var(--el-ok); }
[data-theme="ghost-terminal"] .el-ink-fail  { font-family: var(--el-font-mono); color: var(--el-fail); }

[data-theme="ghost-terminal"] .el-title-xl,
[data-theme="ghost-terminal"] .el-display-specimen {
  font-family: var(--el-font-display);
  font-weight: var(--el-head-weight);
