[data-theme="ghost-terminal"] .el-btn::before { content: "[ "; color: var(--el-mute); }
[data-theme="ghost-terminal"] .el-btn::after  { content: " ]"; color: var(--el-mute); }
[data-theme="ghost-terminal"] .el-btn:hover {
  filter: none;
