[data-theme="ghost-terminal"] .el-btn.ghost::before,
[data-theme="ghost-terminal"] .el-btn.ghost::after,
[data-theme="ghost-terminal"] .el-btn--ghost::before,
[data-theme="ghost-terminal"] .el-btn--ghost::after,
[data-theme="ghost-terminal"] .el-btn--outline::before,
