  --el-mute:         #78614b;
  --el-on-accent:    #fff8f1;

  --el-accent:       #b03c26;   
  --el-accent-hover: #c14a2f;
  --el-accent-soft:  color-mix(in oklab, var(--el-accent) 9%, transparent);

  --el-ok:    #4d6f45;
  --el-warn:  #8a5f17;
  --el-fail:  #8f2f24;
  --el-info:  #42607d;
  --el-live:  #2e7d6e;
  --el-teal:  #2e6f68;

  --el-focus-ring: color-mix(in oklab, var(--el-accent) 80%, transparent);
  --el-overlay:    color-mix(in oklab, var(--el-ink) 40%, transparent);
  --el-shadow-1: 0 1px 2px color-mix(in oklab, var(--el-ink) 7%, transparent),
                 0 1px 8px color-mix(in oklab, var(--el-ink) 4%, transparent);
  --el-shadow-2: 0 6px 20px color-mix(in oklab, var(--el-ink) 9%, transparent),
                 0 18px 44px -14px color-mix(in oklab, var(--el-ink) 18%, transparent);
  --el-shadow-3: 0 16px 60px color-mix(in oklab, var(--el-ink) 14%, transparent),
                 0 36px 96px -28px color-mix(in oklab, var(--el-ink) 26%, transparent);

  
  --el-font-body:    'Inter', system-ui, -apple-system, 'Segoe UI', sans-serif;
  --el-font-display: 'Instrument Serif', 'Prata', Georgia, serif;
  --el-font-serif:   'Instrument Serif', 'Prata', Georgia, serif;
  --el-font-mono:    'IBM Plex Mono', 'SF Mono', Menlo, Consolas, monospace;
  --el-body-weight:  500;

  
  --el-fs-xs:  11px;
  --el-fs-sm:  12px;
  --el-fs-md:  13px;
  --el-fs-lg:  17px;
  --el-fs-xl:  22px;
  --el-fs-2xl: 30px;
  --el-fs-3xl: 42px;

  
  --el-raise-1: 0 1px 2px color-mix(in oklab, var(--el-ink) 7%, transparent),
                0 2px 10px color-mix(in oklab, var(--el-ink) 5%, transparent);
  --el-raise-2: 0 2px 4px color-mix(in oklab, var(--el-ink) 8%, transparent),
                0 16px 40px -12px color-mix(in oklab, var(--el-ink) 20%, transparent);
  --el-raise-3: 0 4px 10px color-mix(in oklab, var(--el-ink) 9%, transparent),
                0 36px 88px -26px color-mix(in oklab, var(--el-ink) 32%, transparent);
  --el-hairline: inset 0 0 0 1px color-mix(in oklab, var(--el-ink) 5%, transparent);
  --el-r-sm: 8px;  --el-r-md: 10px;  --el-r-lg: 14px;  --el-r-xl: 18px;
  --el-bar-h: 0;
  --el-ctl-pad-y: 10px;  --el-ctl-pad-x: 18px;  --el-ctl-min-h: 42px;  --el-card-pad: 28px;
  --el-head-weight: 400;  --el-head-tracking: 0.004em;  --el-head-case: none;
  --el-label-weight: 600;  --el-label-tracking: 0.2em;  --el-label-case: none;
  --el-dur-fast: 200ms;  --el-dur-base: 240ms;  --el-dur-slow: 260ms;
  --el-ease: cubic-bezier(.3, .12, .16, 1);
  --el-ease-quiet: cubic-bezier(.3, .12, .16, 1);
  --el-ring: 0 0 0 3px color-mix(in oklab, var(--el-accent) 16%, transparent);
  --el-ornament: none;
  --el-rule-style: hairline;
  --el-hero-pad: 84px;
  --el-hero-min: 460px;
  --el-measure: 66ch;
  --el-bw-emph: 1px;
}

[data-theme="cream-journal"] body {
  margin: 0;
  color-scheme: light;
  background:
    radial-gradient(1100px 520px at 8% -8%,
      color-mix(in oklab, var(--el-accent) 4.2%, transparent) 0%,
      color-mix(in oklab, var(--el-accent) 2.6%, transparent) 30%,
      color-mix(in oklab, var(--el-accent) 1.1%, transparent) 55%,
      transparent 70%),
    radial-gradient(900px 460px at 108% 108%,
      color-mix(in oklab, var(--el-accent) 3.6%, transparent) 0%,
      color-mix(in oklab, var(--el-accent) 2.2%, transparent) 30%,
      color-mix(in oklab, var(--el-accent) 0.9%, transparent) 55%,
      transparent 70%),
    radial-gradient(color-mix(in oklab, var(--el-ink) 2.5%, transparent) 0.5px, transparent 0.5px),
    radial-gradient(color-mix(in oklab, var(--el-ink) 1.5%, transparent) 0.5px, transparent 0.5px),
    var(--el-bg);
  background-size: auto, auto, 4px 4px, 7px 7px;
  background-position: 0 0, 0 0, 0 0, 2px 3px;
  color: var(--el-ink);
  font-family: var(--el-font-body);
  font-weight: var(--el-body-weight);
  font-size: 16px;
  font-feature-settings: var(--el-font-feat);
  font-optical-sizing: auto;
  line-height: 1.6;
  letter-spacing: 0.004em;
  text-rendering: optimizeLegibility;
  accent-color: var(--el-accent);
  scrollbar-color: var(--el-line-strong) transparent;
}
[data-theme="cream-journal"] body *,
[data-theme="cream-journal"] body *::before,
[data-theme="cream-journal"] body *::after { box-sizing: border-box; }

[data-theme="cream-journal"] .el-banner,
[data-theme="cream-journal"] .el-dialog { font-size: 16px; }

[data-theme="cream-journal"] h1, [data-theme="cream-journal"] h2,
[data-theme="cream-journal"] h3, [data-theme="cream-journal"] h4 {
  font-family: var(--el-font-display);
  font-weight: var(--el-head-weight);
  letter-spacing: var(--el-head-tracking);
  text-transform: var(--el-head-case);
