  font-kerning: normal;
  font-variant-ligatures: common-ligatures;
  line-height: 1.14;
  color: var(--el-ink);
}
[data-theme="cream-journal"] .el-page { padding: var(--el-space-5); max-width: 1280px; margin: 0 auto; }
[data-theme="cream-journal"] .el-display-specimen { font-family: var(--el-font-display); }
[data-theme="cream-journal"] .el-mute-body { color: var(--el-mute); }
[data-theme="cream-journal"] ::selection { background: var(--el-accent); color: var(--el-on-accent); }
[data-theme="cream-journal"] :focus-visible { outline: 2px solid var(--el-focus-ring); outline-offset: 2px; }
[data-theme="cream-journal"] .el-field { display: block; margin-bottom: 14px; }
[data-theme="cream-journal"] .el-field > .el-label { display: block; margin-bottom: 7px; }

[data-theme="cream-journal"] .el-eyebrow {
