[data-theme="kinetic-ink"] {
  color-scheme: dark;
  accent-color: var(--el-accent);
  scrollbar-color: var(--el-line-strong) transparent;

  --el-bg:          #0e0e10;
  --el-panel:       #16161a;
  --el-panel-2:     #1d1d23;
  --el-panel-3:     #27272f;
  --el-line:        #2b2b34;
  --el-line-2:      #222228;
  --el-line-strong: #41414d;
  --el-ink:         #f5f5f7;
  --el-ink-soft:    #a8a8b6;
  --el-mute:        #8f8f9d;
  --el-on-accent:   #0e0e10;
  --el-accent:      #ff3d7f;
  --el-accent-hover: #ff6798;
  --el-accent-soft:  color-mix(in oklab, var(--el-accent) 14%, transparent);
  --el-ok:   #3ddc97;
  --el-warn: #ffc247;
  --el-fail: #ff4d5e;
  --el-info: #7d9bff;
  --el-live: #ff3d7f;
  --el-teal: #46d8c8;
  --el-focus-ring: color-mix(in oklab, var(--el-accent) 62%, transparent);
  --el-overlay:    rgba(8, 8, 10, 0.66);
  --el-font-body:    'Inter', system-ui, -apple-system, sans-serif;
  --el-font-display: 'Clash Display', 'Inter', system-ui, sans-serif;
  --el-font-mono:    'Inter Tight', 'SF Mono', Menlo, Consolas, monospace;
  --el-head-weight:   600;
  --el-head-tracking: -0.02em;
  --el-head-case:     none;
  --el-label-tracking: 0.24em;
  --el-label-case:     uppercase;
  --el-body-weight:   500;
  --el-r-sm: 4px;
  --el-r-md: 7px;
  --el-r-lg: 10px;
  --el-r-xl: 14px;
  --el-raise-1: 0 1px 2px rgba(0, 0, 0, 0.45);
  --el-raise-2: 0 2px 6px rgba(0, 0, 0, 0.5),
                0 14px 34px -14px color-mix(in oklab, var(--el-accent) 12%, transparent),
                0 12px 28px -12px rgba(0, 0, 0, 0.6);
  --el-raise-3: 0 4px 12px rgba(0, 0, 0, 0.5),
                0 30px 64px -16px color-mix(in oklab, var(--el-accent) 16%, transparent),
                0 28px 60px -20px rgba(0, 0, 0, 0.7);
  --el-hairline: inset 0 1px 0 color-mix(in oklab, var(--el-ink) 7%, transparent);
  --el-bar-h: 5px;
  --el-ctl-pad-y: 10px;
  --el-ctl-pad-x: 18px;
  --el-ctl-min-h: 40px;
  --el-card-pad: 22px;
  --el-dur-fast: 140ms;
  --el-dur-base: 280ms;
  --el-dur-slow: 560ms;
  --el-ease: cubic-bezier(0.16, 1, 0.3, 1);
  --el-ornament: grain;
  --el-rule-style: solid;
  --el-hero-pad: 76px;
  --el-hero-min: 440px;
  
  --el-stage-done:    var(--el-ok);
  --el-stage-running: var(--el-accent);
  --el-stage-active:  var(--el-accent);
  --el-stage-stale:   var(--el-mute);
  
  --kin-glow:       color-mix(in oklab, var(--el-accent) 55%, transparent);
  --kin-glow-soft:  color-mix(in oklab, var(--el-accent) 18%, transparent);
  --kin-blush:      #ff8fb8;
  --kin-sweep-ease: cubic-bezier(0.16, 1, 0.3, 1);
}

@supports (transition-timing-function: linear(0, 1)) {
  [data-theme="kinetic-ink"] {
    --kin-sweep-ease: linear(0,
      0.018 3.2%, 0.074 8.6%, 0.157 14.9%, 0.262 21.6%,
      0.385 28.6%, 0.517 35.8%, 0.648 43.3%, 0.768 51.1%,
      0.866 59.4%, 0.94 68.2%, 1 77.6%, 1.028 82.4%,
      1.016 87.6%, 1 93.2%, 1 100%);
  }
}

[data-theme="kinetic-ink"] body {
  margin: 0;
  
  background:
    radial-gradient(1200px 620px at 12% -14%,
      color-mix(in oklab, var(--el-accent) 13%, transparent) 0%,
      color-mix(in oklab, var(--el-accent) 8%, transparent) 30%,
      color-mix(in oklab, var(--el-accent) 3.5%, transparent) 47%,
      transparent 65%),
    radial-gradient(920px 520px at 108% 114%,
      color-mix(in oklab, var(--el-accent) 9%, transparent) 0%,
      color-mix(in oklab, var(--el-accent) 4.5%, transparent) 48%,
      transparent 68%),
    var(--el-bg);
  color: var(--el-ink);
  font-family: var(--el-font-body);
  font-weight: var(--el-body-weight);
  font-feature-settings: var(--el-font-feat, "tnum" 1);
  font-optical-sizing: auto;
  line-height: 1.55;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  text-rendering: optimizeLegibility;
}

[data-theme="kinetic-ink"] .el-display-specimen {
  font-family: var(--el-font-display);
  letter-spacing: var(--el-head-tracking);
  text-transform: var(--el-head-case);
  text-wrap: balance;
}
[data-theme="kinetic-ink"] .el-title-xl {
