}
[data-theme="kinetic-ink"] .el-hero .el-title-xl {
  width: fit-content;
  max-width: 100%;
  
  background: linear-gradient(94deg,
    var(--el-ink) 0%,
    var(--el-ink) 52%,
    color-mix(in oklab, var(--el-ink) 58%, var(--kin-blush)) 74%,
    color-mix(in oklab, var(--el-ink) 26%, var(--kin-blush)) 88%,
    var(--kin-blush) 100%);
  -webkit-background-clip: text;
  background-clip: text;
  -webkit-text-fill-color: transparent;
}
[data-theme="kinetic-ink"] .el-hero .el-title-xl::selection {
  background: var(--el-accent);
  color: var(--el-bg);
  -webkit-text-fill-color: var(--el-bg);
}
[data-theme="kinetic-ink"] .el-body {
  font-family: var(--el-font-body);
  font-weight: var(--el-body-weight);
  font-size: 1.02em;
  line-height: 1.65;
  color: var(--el-ink-soft);
  text-wrap: pretty;
}
[data-theme="kinetic-ink"] .el-mute-body {
  color: var(--el-mute);
