  color: var(--el-mute);
}
[data-theme="kinetic-ink"] .el-mono {
  font-family: var(--el-font-mono);
  font-variant-numeric: tabular-nums;
  letter-spacing: 0.01em;
  color: var(--el-ink);
}
[data-theme="kinetic-ink"] .el-big-num {
  font-family: var(--el-font-display);
  font-weight: var(--el-head-weight);
  letter-spacing: -0.02em;
  font-variant-numeric: tabular-nums;
}
[data-theme="kinetic-ink"] .el-ink-ok   { color: var(--el-ok); }
[data-theme="kinetic-ink"] .el-ink-fail { color: var(--el-fail); }
[data-theme="kinetic-ink"] .el-publisher {
  font-family: var(--el-font-mono);
  font-size: var(--el-fs-xs);
  letter-spacing: var(--el-label-tracking);
  text-transform: var(--el-label-case);
  color: var(--el-accent);
}
[data-theme="kinetic-ink"] ::selection {
  background: var(--el-accent);
  color: var(--el-bg);
}

[data-theme="kinetic-ink"] .el-hero {
  position: relative;
  overflow: hidden;
  border-bottom: 1px solid var(--el-line-2);
}
[data-theme="kinetic-ink"] .el-hero::after {
  content: "";
  position: absolute;
  inset: 0;
  background:
    radial-gradient(640px 320px at 88% 0%,
      color-mix(in oklab, var(--el-accent) 15%, transparent) 0%,
      color-mix(in oklab, var(--el-accent) 8%, transparent) 38%,
      transparent 64%),
    radial-gradient(480px 260px at 2% 100%,
      color-mix(in oklab, var(--el-accent) 7%, transparent) 0%,
      transparent 74%);
  pointer-events: none;
}

[data-theme="kinetic-ink"] .el-eyebrow {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  font-family: var(--el-font-body);
  font-size: var(--el-fs-xs);
  font-weight: 600;
  letter-spacing: 0.26em;
  text-transform: uppercase;
  color: var(--el-ink-soft);
