[data-theme="kinetic-ink"] .el-eyebrow::before {
  content: "";
  width: 18px;
  height: 2px;
  transform-origin: left center;
  background: linear-gradient(90deg,
    var(--el-accent) 0%,
    color-mix(in oklab, var(--el-accent) 52%, var(--kin-blush)) 100%);
  box-shadow: 0 0 10px var(--kin-glow);
}
[data-theme="kinetic-ink"] .el-eyebrow::after {
  content: "";
  width: 64px;
  height: 1px;
  background: linear-gradient(90deg,
    var(--el-line-strong) 0%,
    color-mix(in oklab, var(--el-line-strong) 42%, transparent) 58%,
    transparent 100%);
