[data-theme="kinetic-ink"] .el-reader p .el-eyebrow {
  display: inline;
}
[data-theme="kinetic-ink"] .el-reader p .el-eyebrow::before,
[data-theme="kinetic-ink"] .el-reader p .el-eyebrow::after {
  content: none;
}

[data-theme="kinetic-ink"] .el-btn {
  --kin-btn-glow: 7%;
  background:
    linear-gradient(180deg,
      color-mix(in oklab, var(--el-accent) var(--kin-btn-glow, 7%), transparent) 0%,
      transparent 52%),
    linear-gradient(180deg, var(--el-panel-2) 0%, color-mix(in oklab, var(--el-panel-2) 72%, var(--el-bg)) 100%);
  color: var(--el-ink);
  border: 1px solid var(--el-line-strong);
  border-radius: var(--el-r-md);
  box-shadow: var(--el-hairline);
}
[data-theme="kinetic-ink"] .el-btn::after {
  content: "";
  position: absolute;
  left: 0;
  right: 0;
  bottom: 0;
  height: 2px;
  border-radius: 0 0 calc(var(--el-r-md) - 1px) calc(var(--el-r-md) - 1px);
  transform: scaleX(0.2);
  transform-origin: left center;
  background: linear-gradient(90deg,
    var(--el-accent) 0%,
    color-mix(in oklab, var(--el-accent) 60%, var(--kin-blush)) 64%,
    var(--kin-blush) 100%);
  box-shadow: 0 0 8px var(--kin-glow-soft);
}
[data-theme="kinetic-ink"] .el-btn:hover {
  --kin-btn-glow: 13%;
  border-color: color-mix(in oklab, var(--el-accent) 45%, var(--el-line));
  color: var(--el-ink);
}
[data-theme="kinetic-ink"] .el-btn:hover::after {
  transform: scaleX(1);
  box-shadow: 0 0 12px var(--kin-glow);
}
[data-theme="kinetic-ink"] .el-btn:active {
  transform: var(--el-press);
  box-shadow: none;
  --kin-btn-glow: 11%;
}
[data-theme="kinetic-ink"] .el-btn:focus-visible {
  outline: 2px solid color-mix(in oklab, var(--el-accent) 80%, transparent);
  outline-offset: 2px;
}
[data-theme="kinetic-ink"] .el-btn:disabled,
[data-theme="kinetic-ink"] .el-btn[aria-disabled="true"] {
  opacity: 0.45;
  cursor: not-allowed;
  transform: none;
  box-shadow: none;
  border-color: var(--el-line);
