[data-theme="kinetic-ink"] .el-btn:disabled::after,
[data-theme="kinetic-ink"] .el-btn[aria-disabled="true"]::after {
  transform: scaleX(0.2);
  box-shadow: none;
  opacity: 0.28;
}
[data-theme="kinetic-ink"] .el-btn.ghost,
[data-theme="kinetic-ink"] .el-btn--ghost,
[data-theme="kinetic-ink"] .el-btn--outline {
  background: transparent;
  border-color: var(--el-line);
  color: var(--el-ink-soft);
  box-shadow: none;
