[data-theme="kinetic-ink"] .el-btn.ghost:hover,
[data-theme="kinetic-ink"] .el-btn--ghost:hover,
[data-theme="kinetic-ink"] .el-btn--outline:hover {
  color: var(--el-ink);
  background: var(--el-accent-soft);
  border-color: color-mix(in oklab, var(--el-accent) 40%, transparent);
}
[data-theme="kinetic-ink"] .el-btn.ghost:active,
[data-theme="kinetic-ink"] .el-btn--ghost:active,
