  --el-font-display: 'Unbounded', 'Inter', system-ui, sans-serif;
  --el-font-mono:    'Inter Tight', 'SF Mono', Menlo, Consolas, monospace;
  
  --el-head-weight:   700;
  --el-head-tracking: 0em;
  --el-head-case:     uppercase;
  --el-label-tracking: 0.16em;
  --el-label-case:     lowercase;
  --el-body-weight:   500;
  --el-r-sm: 2px;
  --el-r-md: 3px;
  --el-r-lg: 4px;
  --el-r-xl: 6px;
  --el-raise-1: 0 1px 2px rgba(0, 0, 0, 0.5);
  --el-raise-2: 0 2px 8px rgba(0, 0, 0, 0.55),
                0 12px 30px -12px color-mix(in oklab, var(--el-accent) 8%, transparent),
                0 10px 26px -10px rgba(0, 0, 0, 0.65);
  --el-raise-3: 0 6px 16px rgba(0, 0, 0, 0.55),
                0 28px 64px -16px color-mix(in oklab, var(--el-accent) 10%, transparent),
