  --el-bar-h: 3px;
  --el-ctl-pad-y: 9px;
  --el-ctl-pad-x: 16px;
  --el-ctl-min-h: 40px;
  --el-card-pad: 20px;
  --el-dur-fast: 110ms;
  --el-dur-base: 220ms;
  --el-dur-slow: 480ms;
  --el-ease: cubic-bezier(0.76, 0, 0.24, 1);
  --el-ornament: grid;
  --el-rule-style: double;
  --el-hero-pad: 72px;
  --el-hero-min: 440px;
  
  --el-stage-done:    var(--el-ok);
