}

[data-theme="aperture-motion"] body {
  margin: 0;
  
  background:
    radial-gradient(1200px 620px at 12% -14%,
      color-mix(in oklab, var(--el-accent) 12%, transparent) 0%,
      color-mix(in oklab, var(--el-accent) 7%, transparent) 28%,
